#!/usr/bin/env python3
import html, json, re, shutil
from pathlib import Path

root = Path(__file__).resolve().parent
out = root.parent / 'docs'
if out.exists(): shutil.rmtree(out)
out.mkdir(exist_ok=True)

def inline(s):
    s = html.escape(s)
    s = re.sub(r'\[([^]]+)\]\((https://[^ )]+)\)', r'<a href="\2">\1 ↗</a>', s)
    s = re.sub(r'`([^`]+)`', r'<code>\1</code>', s)
    s = re.sub(r'\*\*([^*]+)\*\*', r'<strong>\1</strong>', s)
    return s

def render(text):
    blocks=[]
    for chunk in re.split(r'\n\s*\n', text.strip()):
        lines=chunk.splitlines()
        if lines[0].startswith('# '): blocks.append('<h2>'+inline(lines[0][2:])+'</h2>')
        elif lines[0].startswith('## '): blocks.append('<h3>'+inline(lines[0][3:])+'</h3>')
        elif all(x.startswith('|') for x in lines) and len(lines) > 2:
            rows=[[inline(c.strip()) for c in line.strip().strip('|').split('|')] for line in lines]
            blocks.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+c+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows[2:])+'</tbody></table></div>')
        elif all(re.match(r'^\d+\. ',x) for x in lines): blocks.append('<ol>'+''.join('<li>'+inline(re.sub(r'^\d+\. ', '',x))+'</li>' for x in lines)+'</ol>')
        elif all(x.startswith('- ') for x in lines): blocks.append('<ul>'+''.join('<li>'+inline(x[2:])+'</li>' for x in lines)+'</ul>')
        else: blocks.append('<p>'+inline(' '.join(lines))+'</p>')
    return '\n'.join(blocks)

articles=[]
for f in sorted((root/'knowledge').glob('*.md')):
    t=f.read_text(); title=t.splitlines()[0][2:]
    if f.stem == '11-mesh-20261116' and '\n## Archived activity log\n' in t:
        current, history = t.split('\n## Archived activity log\n', 1)
        body = render(current) + '<details class="activity-log" id="mesh-activity-log"><summary>Expand archived activity log and failed attempts</summary><div>' + render(history) + '</div></details>'
    else:
        body = render(t)
    body = body.replace("<p>MESH_TOPOLOGY_DIAGRAMS</p>", "<div class=\"case-image overview\"><img src=\"topologies/wired-mesh-baseline.svg\" alt=\"Baseline wired endpoints and integrated radio mesh\"></div><div class=\"case-image overview\"><img src=\"topologies/wired-mesh-swapped.svg\" alt=\"Requested radio-swapped mesh layout, not yet qualified\"></div>")
    body = body.replace("<p>AP_STA_DIAGRAM</p>", "<div class=\"case-image overview\"><img src=\"topologies/router-ap-sta.svg\" alt=\"Router-local access point and station comparison\"></div>")
    articles.append((f.stem,title,body))
